import (
	"bufio"
	"fmt"
	"os"
)

func isLucky(x int64) bool {
	if x <= 0 {
		return false
	}
	for x > 0 {
		d := x % 10
		if d != 4 && d != 7 {
			return false
		}
		x /= 10
	}
	return true
}

func main() {
	in := bufio.NewReader(os.Stdin)
	var n, k int64
	if _, err := fmt.Fscan(in, &n, &k); err != nil {
		return
	}

	const LIM = 20
	if n <= LIM {
		// generate k-th permutation of 1..n
		// total permutations = n!
		fact := make([]int64, LIM+1)
		fact[0] = 1
		for i := 1; i <= int(n); i++ {
			fact[i] = fact[i-1] * int64(i)
			if fact[i] > k { // cap, but we only need up to n
				// no need to cap here
			}
		}
		if k > fact[n] {
			fmt.Println(-1)
			return
		}
		// k is 1-based
		k--
		used := make([]bool, n+1)
		perm := make([]int64, n+1) // 1-based
		for pos := int64(1); pos <= n; pos++ {
			for v := int64(1); v <= n; v++ {
				if used[v] {
					continue
				}
				rem := n - pos
				cnt := fact[rem]
				if k >= cnt {
					k -= cnt
				} else {
					perm[pos] = v
					used[v] = true
					break
				}
			}
		}
		var ans int64
		for i := int64(1); i <= n; i++ {
			if isLucky(i) && isLucky(perm[i]) {
				ans++
			}
		}
		fmt.Println(ans)
		return
	}

	// n > 20
	// prefix 1..(n-20) is fixed in all permutations
	m := int64(LIM)
	start := n - m + 1 // first index of the variable tail
	// compute m! to check k
	fact := make([]int64, LIM+1)
	fact[0] = 1
	for i := 1; i <= LIM; i++ {
		fact[i] = fact[i-1] * int64(i)
	}
	if k > fact[LIM] {
		fmt.Println(-1)
		return
	}
	k--

	// build k-th permutation of tail values: start..n
	used := make([]bool, m+1)
	tail := make([]int64, m+1) // 1-based positions within tail
	for pos := int64(1); pos <= m; pos++ {
		for idx := int64(1); idx <= m; idx++ {
			if used[idx] {
				continue
			}
			rem := m - pos
			cnt := fact[rem]
			if k >= cnt {
				k -= cnt
			} else {
				used[idx] = true
				tail[pos] = start + idx - 1
				break
			}
		}
	}

	var ans int64
	// positions 1..(start-1): a[i] = i
	for i := int64(1); i < start; i++ {
		if isLucky(i) {
			ans++
		}
	}
	// positions start..n: use tail
	for pos := int64(0); pos < m; pos++ {
		i := start + pos
		val := tail[pos+1]
		if isLucky(i) && isLucky(val) {
			ans++
		}
	}
	fmt.Println(ans)
