	in := bufio.NewReader(os.Stdin)
	var n, k int64
	if _, err := fmt.Fscan(in, &n, &k); err != nil {
		return
	}

	// Precompute factorials up to 20 (since 20! fits in 64-bit and > 1e18)
	const MAXF = 20
	fact := make([]int64, MAXF+1)
	fact[0] = 1
	for i := 1; i <= MAXF; i++ {
		fact[i] = fact[i-1] * int64(i)
	}

	// If n > 20, only last 20 positions affect lexicographic permutations
	if n > MAXF {
		if k > fact[MAXF] {
			fmt.Println(-1)
			return
		}
	} else {
		if k > fact[n] {
			fmt.Println(-1)
			return
		}
	}

	// Build the k-th permutation for the last m positions
	m := int64(MAXF)
	if n < MAXF {
		m = n
	}

	// positions from startFixed+1 to n are permuted
	startFixed := n - m

	// available numbers for permutation: startFixed+1 .. n
	avail := make([]int64, 0, m)
	for i := startFixed + 1; i <= n; i++ {
		avail = append(avail, i)
	}

	perm := make([]int64, m)
	k-- // zero-based
	for i := int64(0); i < m; i++ {
		remain := m - i - 1
