		if remain <= MAXF {
			f = fact[remain]
		}
		idx := k / f
		k = k % f
		perm[i] = avail[idx]
		avail = append(avail[:idx], avail[idx+1:]...)
	}

	// Count lucky positions where index and value are lucky
	var ans int64 = 0

	// First part: positions 1..startFixed, ai = i
	for i := int64(1); i <= startFixed; i++ {
		if isLucky(i) {
			ans++
		}
	}

	// Second part: positions startFixed+1..n, using perm
	for i := int64(0); i < m; i++ {
		pos := startFixed + 1 + i
		val := perm[i]
		if isLucky(pos) && isLucky(val) {
			ans++
		}
	}

	fmt.Println(ans)
