	for i := int64(0); i < int64(m); i++ {
		pos := start + i
		if isLucky(pos) && isLucky(permSuffix[i]) {
			ans++
		}
	}
	fmt.Println(ans)
}

package main

import (
	"bufio"
	"fmt"
	"os"
)

func isLucky(x int64) bool {
	if x <= 0 {
		return false
	}
	for x > 0 {
		d := x % 10
		if d != 4 && d != 7 {
			return false
		}
		x /= 10
	}
	return true
}

func main() {
	in := bufio.NewReader(os.Stdin)
	var n, k int64
	if _, err := fmt.Fscan(in, &n, &k); err != nil {
		return
	}

	const LIM = 20
	if n > LIM {
		// prefix 1..(n-LIM) is fixed
		prefix := n - LIM
		// check if k-th permutation of last LIM elements exists
		// permutations count = LIM!
		fact := int64(1)
		for i := int64(2); i <= LIM; i++ {
			fact *= i
			if fact > k { // we only need to know if fact >= k
				break
			}
		}
		if k > fact {
			fmt.Println(-1)
			return
		}

		// count lucky positions in prefix: i where i and ai=i are lucky
		ans := int64(0)
		for i := int64(1); i <= prefix; i++ {
			if isLucky(i) {
				ans++
			}
		}

		// build k-th permutation of numbers prefix+1..n
		m := int(n - prefix)
		avail := make([]int64, m)
		for i := 0; i < m; i++ {
			avail[i] = int64(prefix + 1 + int64(i))
		}
		perm := make([]int64, m)

		k-- // 0-based
		for i := 0; i < m; i++ {
			rem := m - i - 1
			f := int64(1)
			for j := 2; j <= rem; j++ {
				f *= int64(j)
				if f > k {
					break
				}
			}
			var idx int64
			if rem > 0 {
				if k >= f {
					idx = k / f
				} else {
					idx = 0
				}
			} else {
				idx = 0
			}
			perm[i] = avail[idx]
			avail = append(avail[:idx], avail[idx+1:]...)
			if rem > 0 {
				k %= f
			}
		}

		// count lucky positions in suffix
		for i := 0; i < m; i++ {
			pos := int64(prefix + 1 + int64(i))
			if isLucky(pos) && isLucky(perm[i]) {
				ans++
			}
		}
		fmt.Println(ans)
	} else {
		// n <= LIM: full permutation
		// check if k-th permutation exists: n!
		fact := int64(1)
		for i := int64(2); i <= n; i++ {
			fact *= i
			if fact > k {
				break
			}
		}
		if k > fact {
			fmt.Println(-1)
			return
		}

		avail := make([]int64, n)
		for i := int64(0); i < n; i++ {
			avail[i] = i + 1
		}
		perm := make([]int64, n)

		k-- // 0-based
		for i := int64(0); i < n; i++ {
			rem := n - i - 1
			f := int64(1)
			for j := int64(2); j <= rem; j++ {
				f *= j
				if f > k {
					break
				}
			}
			var idx int64
			if rem > 0 {
				if k >= f {
					idx = k / f
				} else {
					idx = 0
				}
			} else {
				idx = 0
			}
			perm[i] = avail[idx]
			avail = append(avail[:idx], avail[idx+1:]...)
			if rem > 0 {
				k %= f
			}
		}

		ans := int64(0)
		for i := int64(0); i < n; i++ {
			pos := i + 1
			if isLucky(pos) && isLucky(perm[i]) {
				ans++
			}
		}
		fmt.Println(ans)
	}
}
